const i03RecoverCleanup = `-- name: I03RecoverCleanup :execrows
UPDATE b08_intents SET cleanup_generation=cleanup_generation+1,cleanup_task_id=NULL,cleanup_epoch=?,cleanup_deadline=?
WHERE cleanup_id=? AND cleanup_task_id=? AND cleanup_state='pending' AND cleanup_generation=?
`

type I03RecoverCleanupParams struct {
	CleanupEpoch      sql.NullInt64
	CleanupDeadline   sql.NullString
	CleanupID         string
	CleanupTaskID     sql.NullString
	CleanupGeneration int64
}

func (q *Queries) I03RecoverCleanup(ctx context.Context, arg I03RecoverCleanupParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, i03RecoverCleanup,
		arg.CleanupEpoch,
		arg.CleanupDeadline,
		arg.CleanupID,
		arg.CleanupTaskID,
		arg.CleanupGeneration,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

