const i03RetiredTasks = `-- name: I03RetiredTasks :many
SELECT l.id,l.revision,l.suffix_digest,t.task_id FROM i03_target_links t JOIN b06_internal_links l ON l.id=t.link_id
JOIN tasks k ON k.id=t.task_id JOIN task_nodes n ON n.task_id=k.id AND n.node_id=t.node_id
WHERE t.action='retire' AND l.state='retiring' AND k.state='succeeded' AND k.subject_id=l.id
AND n.applied=1 AND n.cleanup_state='confirmed' ORDER BY l.id LIMIT 64
`

type I03RetiredTasksRow struct {
	ID           string
	Revision     int64
	SuffixDigest string
	TaskID       string
}

func (q *Queries) I03RetiredTasks(ctx context.Context) ([]I03RetiredTasksRow, error) {
	rows, err := q.db.QueryContext(ctx, i03RetiredTasks)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []I03RetiredTasksRow
	for rows.Next() {
		var i I03RetiredTasksRow
		if err := rows.Scan(
			&i.ID,
			&i.Revision,
			&i.SuffixDigest,
			&i.TaskID,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

