const i03UnarmedIdentity = `-- name: I03UnarmedIdentity :one
SELECT NOT EXISTS(SELECT 1 FROM b04_target_grants g JOIN b04_targets t USING(task_id,node_id)
WHERE g.identity_id=? AND (t.phase!='queued' OR t.fetched!=0)) AS unarmed
`

func (q *Queries) I03UnarmedIdentity(ctx context.Context, identityID string) (bool, error) {
	row := q.db.QueryRowContext(ctx, i03UnarmedIdentity, identityID)
	var unarmed bool
	err := row.Scan(&unarmed)
	return unarmed, err
}
